    map:"moses", region:"exodus", lat:30.57, lng:32.27, seq:8,
    geo:"나일 삼각주 동편 끝 — 라암셋에서 출발 후 첫 번째 진영. 애굽 경계 지점. 나일 강이 여러 지류로 갈라져 지중해로 드는 광대한 충적 삼각주로, 해마다 범람이 남긴 비옥한 흙 덕에 고대 이집트 최대의 곡창이었다. 평평하고 물이 풍부한 저지대다 | 고도: 해발 약 20m (나일 동부)",
