       bg:"출애굽과 광야 언약 공동체의 여정 가운데 38년 광야 유랑, 출애굽 1세대 소멸을 둘러싸고 벌어진 일이다. 가데스 바네아의 불신앙 판결 이후 38년간 광야 유랑. 출애굽 1세대(갈렙·여호수아 제외)가 모두 광야에서 사망. 하나님이 만나·구름·불기둥으로 계속 돌보심.",
