       bg:"출애굽과 광야 언약 공동체의 여정 가운데 고라의 반역, 땅이 삼킴을 둘러싸고 벌어진 일이다. 레위 지파 고라와 르우벤 지파 다단·아비람이 250명 지도자들과 함께 모세의 권위에 도전. 땅이 갈라져 고라 무리를 삼킴. 250명이 불에 탐.",
