       ref:"눅 2:1-20",
       bg:"예수 그리스도의 공생애 가운데 예수 그리스도 탄생을 둘러싸고 벌어진 일이다. 아우구스투스 황제 호적 명령으로 요셉과 마리아가 베들레헴으로 이동. 여관에 자리가 없어 구유에 아기를 뉘임. 천사들이 들판의 목자들에게 탄생을 알림. 온 백성에게 미칠 큰 기쁨의 좋은 소식.",
