       bg:"예수 그리스도의 공생애 가운데 동방박사 방문을 둘러싸고 벌어진 일이다. 동방에서 별을 보고 박사들이 방문. 황금·유향·몰약 예물. 헤롯이 위기감을 느껴 박사들에게 아기 위치 알리길 요청. 박사들이 꿈으로 경고를 받아 다른 길로 귀국.",
