       desc:"예수님 세례 — 갈릴리에서 요단 강으로 와 요한에게 세례를 받으심. 물에서 올라올 때 성령이 비둘기같이 임함. 하늘에서 소리: 이는 내 사랑하는 아들이요 내 기뻐하는 자라. 삼위일체 하나님이 동시에 나타난 유일한 장면",
