       desc:"겟세마네 기도 — 아버지여 할만 하면 이 잔을 내게서 지나가게 하옵소서. 그러나 내 원대로 마시옵고 아버지의 원대로 하옵소서. 땀이 핏방울처럼. 세 번 기도. 제자들은 잠들어 있음. 유다가 무리를 이끌고 옴",
