       bg:"예수 그리스도의 공생애 가운데 대위임령을 둘러싸고 벌어진 일이다. 예수님이 갈릴리 산에서 제자들에게: 하늘과 땅의 모든 권세를 내게 주셨으니 너희는 가서 모든 민족을 제자로 삼으라. 세례를 베풀고 모든 것을 가르쳐 지키게 하라. 세상 끝날까지 내가 너희와 항상 함께 있겠다.",
