    geo:"시리아 안디옥 — 바나바와 분리 후 실라와 함께 2차 선교 출발. 오론테스 강변에 자리한 대도시로, 지중해 항구와 가까우면서 동방 대상로의 출발점이었다. 강과 산으로 둘러싸인 비옥한 분지에 세워졌다 | 고도: 해발 약 70m (안디옥)",
