       desc:"성경 상고, 귀족적 수용 — 베뢰아에 있는 사람들은 간절한 마음으로 말씀을 받고 이것이 그러한가 하여 날마다 성경을 상고하므로. 많은 사람 믿음·귀부인들도 적지 않음",
