       ref:"(클레멘스·에우세비우스 전승)",
       bg:"출애굽과 광야 언약 공동체의 여정 가운데 아쿠아 살비아에서 참수 순교 전승을 둘러싸고 벌어진 일이다. 로마 교외 아쿠아 살비아(현 트레 폰타네)에서 참수. 베드로는 바티칸에서 거꾸로 십자가. 클레멘스·에우세비우스·히에로니무스 기록.",
