       desc:"두 정탐꾼 파송 — 여호수아가 두 사람을 가만히 정탐꾼으로 보냄. 그들이 기생 라합의 집에 유숙. 라합: 여호와가 이 땅을 너희에게 주신 줄을 압니다. 붉은 줄을 창에 매달면 구원 약속",
       ref:"수 2:1-24",
       bg:"가나안 정복기의 정황 속에서 두 정탐꾼 파송을 둘러싸고 벌어진 일이다. 여호수아가 두 사람을 가만히 정탐꾼으로 보냄. 그들이 기생 라합의 집에 유숙. 라합: 여호와가 이 땅을 너희에게 주신 줄을 압니다. 붉은 줄을 창에 매달면 구원 약속.",
