       desc:"요단 강 기적 도하 — 법궤를 멘 제사장들의 발이 요단 강에 닿자 아담 성읍에서부터 물이 끊어짐. 이스라엘이 마른 땅으로 건넘. 하나님: 내가 모세를 높인 것처럼 여호수아를 높이겠다",
       ref:"수 3:1-17",
       bg:"가나안 정복기의 정황 속에서 요단 강 기적 도하를 둘러싸고 벌어진 일이다. 법궤를 멘 제사장들의 발이 요단 강에 닿자 아담 성읍에서부터 물이 끊어짐. 이스라엘이 마른 땅으로 건넘. 하나님: 내가 모세를 높인 것처럼 여호수아를 높이겠다.",
