       ref:"수 24:1-28",
       bg:"가나안 정복기의 정황 속에서 여호수아 1차 고별 설교를 둘러싸고 벌어진 일이다. 세겜에 이스라엘 지도자들을 소집. 아브라함 선택→애굽→모세→광야→가나안까지 하나님의 신실하심 회고. 여호수아: 오직 나와 내 집은 여호와를 섬기겠노라.",
