    geo:"가나안 중부 — 에발 산과 그리심 산 사이. 아브람이 가나안 도착 후 처음 들른 장소. 지중해와 요단 계곡 사이의 좁은 땅으로, 서쪽 해안 평야·중앙 산지·동쪽 요단 저지로 뚜렷이 나뉜다. 남북으로 가는 대상로가 지나는 비옥한 회랑지대였다 | 고도: 해발 약 540m (에브라임 산지)",
