       desc:"이삭 바침·대속 숫양·여호와 이레 — 하나님이 아브라함에게 독자 이삭을 번제로 드리라 명함. 아브라함이 순종하여 모리아 산으로 올라감. 이삭이 스스로 나무를 지고 오르며 '번제할 어린 양은 어디 있나이까' 물음. 천사가 막는 순간 숫양이 나타나 대신 드려짐. 여호와 이레(여호와가 준비하신다)",
