       bg:"이스라엘의 지혜 전통 속에서 에베소 교회의 감독을 둘러싸고 벌어진 일이다. 바울에게서 에베소 교회를 위임받아 거짓 교사를 경계하고 바른 교훈과 교회 질서를 세움. 디모데전후서를 통해 목회와 지도자의 자격에 관한 지침을 받은 젊은 목회자(딤전 1:3).",
