       desc:"스불론의 소사사 엘론 — 스불론 지파 출신으로 10년간 이스라엘을 다스림. 별다른 전쟁 기록 없이 평온한 시기를 보내고 아얄론에 장사됨. 짧지만 안정된 통치로 이름을 남김(삿 12:11-12)",
