       ref:"출 32장",
       bg:"시내산에서 하나님과 언약을 맺은 직후, 모세가 산에 오래 머무는 사이 백성은 눈에 보이는 신을 요구했고 아론이 금송아지를 만든다. 하나님의 진노 앞에서 모세는 \"주의 백성을 생각하소서\"라며 중보했고, 깨어진 돌판을 대신할 새 돌판으로 언약이 갱신된다.",
