       ref:"출 15:20-21",
       bg:"출애굽과 광야 언약 공동체의 여정 가운데 미리암의 승전가를 둘러싸고 벌어진 일이다. 홍해를 건넌 후 미리암이 소고를 잡고 모든 여인을 이끌며 춤추고 노래함. '여호와를 찬송하라 그는 높고 영화로우심이요 말과 그 탄 자를 바다에 던지셨도다'. 성경 최초의 여성 예배 인도자(출 15:20-21).",
