       desc:"구스 여인 문제·나병 징계·모세의 중보 — 아론과 함께 모세의 구스인 아내 문제로 비방. '여호와께서 모세와만 말씀하셨느냐 우리와도 말씀하지 않으셨느냐'. 하나님이 진노하여 미리암에게 나병을 내리심. 모세의 기도로 7일 후 치유됨(민 12장)",
