       desc:"기독교 최초 순교자 — 산헤드린 앞에서 아브라함부터 솔로몬까지 이스라엘 역사를 설파하고 '너희는 항상 성령을 거스른다' 책망. '보라 하늘이 열리고 인자가 하나님 우편에 서신 것을 본다' 외침. 성문 밖에서 돌에 맞아 순교. '주여 이 죄를 저들에게 돌리지 마소서' 기도. 사울이 증인들의 옷을 지킴(행 7장)",
