       bg:"왕의 궁정 선지자였던 나단은 먼저 다윗에게 영원한 왕위의 언약을 전하는 은혜의 통로였다가, 훗날 같은 입으로 왕의 범죄를 목숨을 걸고 지적하는 책망의 통로가 된다. 비유로 먼저 스스로 판결하게 한 뒤 정면으로 죄를 드러내는 그의 지혜는 왕의 마음을 열어 회개에 이르게 한다.",
