       desc:"음란한 아내를 다시 찾는 사랑 — 하나님의 명령으로 음란한 여인 고멜과 결혼해 자녀를 낳음. 고멜이 다른 남자에게로 떠나갔으나 하나님의 지시로 다시 은 15개와 보리로 값을 치르고 그녀를 데려와 사랑함. 이 결혼 자체가 우상에게 마음이 떠난 이스라엘을 향한 여호와의 변함없는 사랑을 보여주는 살아있는 비유가 됨",
