       desc:"바울의 변론을 들음 — 헤롯 아그립바 1세의 아들로 유대 종교 문제에 정통. 베스도의 요청으로 누이 베르니게와 함께 화려한 위엄을 갖추고 바울의 변론을 들으러 옴. 바울이 자신의 회심과 부활 신앙을 담대히 증거하자 '네가 적은 말로 나를 권하여 그리스도인이 되게 하려 하는도다' 반응. 재판 후 베스도에게 '이 사람은 만일 가이사에게 상소하지 아니하였더라면 놓을 수 있을 뻔하였다' 말함",
