       bg:"자연재해라는 눈에 보이는 재앙을 통해 요엘은 백성에게 형식적 회개가 아닌 마음의 찢어짐을 촉구하며, 그 심판의 경고 너머에 있는 성령 부어주심의 은혜로운 미래를 함께 내다본다.",
