       desc:"까닭 없는 고난과 하나님의 응답 — 동방에서 가장 부유하고 온전한 자였으나 하루아침에 자녀와 재산을 모두 잃고 온몸에 악창이 남. '주신 이도 여호와시요 거두신 이도 여호와시오니 여호와의 이름이 찬송을 받으실지니이다' 고백. 세 친구의 정죄성 위로와 엘리후의 훈계를 거친 뒤, 마침내 폭풍우 가운데 하나님이 직접 응답하시며 창조 세계의 광대함을 보이심. 욥이 '내가 주께 대하여 귀로 듣기만 하였사오나 이제는 눈으로 주를 뵈옵나이다' 회개. 이후 이전보다 갑절의 복을 받음",
